using System.Collections.Generic;
using System.IO;
using System.Linq;
using Draftmaster.MasterDraft;
using NUnit.Framework;

// Master Draft's car catalogue: Assets/Resources/MasterDraft/Cars.json (generated by Tools/masterdraft_export.py
// from Draftmaster 2's DriverNames.cs) read through Core's CarCatalog. Engine-free — reads the files off disk —
// so it also runs under `dotnet test Tools/HeadlessTests`.
public class MasterDraftCarCatalogTests
{
    // DM2's winnable carsets that have livery sprites, and how many cars each exports. A change here means the
    // DM2 data or the sprites changed: re-run the export script and update these on purpose.
    static readonly Dictionary<string, int> ExpectedCounts = new Dictionary<string, int>
    {
        { "cup20", 48 }, { "cup22", 46 }, { "cup23", 44 }, { "cup24", 45 },
        { "dmc15", 53 }, { "irc00", 12 }, { "irl23", 35 }, { "irl24", 34 },
    };

    static string projectRoot;

    // The project root, found by walking up from the test binary (headless) or the working directory (Unity).
    static string ProjectRoot()
    {
        if (projectRoot != null) return projectRoot;
        foreach (var start in new[] { TestContext.CurrentContext.TestDirectory, Directory.GetCurrentDirectory() })
        {
            for (var dir = new DirectoryInfo(start); dir != null; dir = dir.Parent)
                if (File.Exists(Path.Combine(dir.FullName, "Assets", "Resources", "MasterDraft", "Cars.json")))
                    return projectRoot = dir.FullName;
        }
        Assert.Fail("Assets/Resources/MasterDraft/Cars.json not found above " + TestContext.CurrentContext.TestDirectory);
        return null;
    }

    static string ResourcesDir => Path.Combine(ProjectRoot(), "Assets", "Resources");

    static string ReadJson() => File.ReadAllText(Path.Combine(ResourcesDir, CarCatalog.ResourcePath + ".json"));

    static CarCatalog Load()
    {
        var catalog = CarCatalog.FromJson(ReadJson());
        Assert.IsNotNull(catalog, "Cars.json did not parse");
        return catalog;
    }

    [Test]
    public void FileParsesAndKeepsEveryRow()
    {
        var file = (CarCatalogFile)ProfileJson.Read(ReadJson(), typeof(CarCatalogFile));
        Assert.IsNotNull(file);
        Assert.AreEqual(1, file.version);
        var catalog = new CarCatalog(file);
        Assert.AreEqual(file.cars.Count, catalog.Count, "the catalogue dropped rows (blank or repeated ids)");
        Assert.AreEqual(ExpectedCounts.Values.Sum(), catalog.Count);
    }

    [Test]
    public void IdsAreUniqueAndFollowTheScheme()
    {
        var file = (CarCatalogFile)ProfileJson.Read(ReadJson(), typeof(CarCatalogFile));
        var dupes = file.cars.GroupBy(c => c.id).Where(g => g.Count() > 1).Select(g => g.Key).ToList();
        CollectionAssert.IsEmpty(dupes, "duplicate car ids");
        foreach (var c in file.cars)
        {
            Assert.AreEqual(CarCatalog.IdFor(c.carset, c.number), c.id);
            Assert.AreEqual(c.carset + "livery" + c.number, c.livery, c.id);
            Assert.That(c.number, Is.InRange(0, 100), c.id);
        }
    }

    [Test]
    public void EveryLiverySpriteExists()
    {
        var missing = Load().Cars.Where(c => !File.Exists(Path.Combine(ResourcesDir, c.livery + ".png")))
            .Select(c => c.id).ToList();
        CollectionAssert.IsEmpty(missing, "cars whose livery sprite is not in Assets/Resources");
    }

    [Test]
    public void EveryCarHasRarityTypeAndIdentity()
    {
        foreach (var c in Load().Cars)
        {
            Assert.That(c.rarity, Is.InRange(CarCatalog.MinRarity, CarCatalog.MaxRarity), c.id);
            Assert.IsTrue(DriverTypes.IsValid(c.type), $"{c.id}: driver type '{c.type}'");
            Assert.IsFalse(string.IsNullOrEmpty(c.driver), c.id + ": no driver");
            Assert.IsFalse(string.IsNullOrEmpty(c.team), c.id + ": no team");
            Assert.IsFalse(string.IsNullOrEmpty(c.manufacturer), c.id + ": no manufacturer");
        }
    }

    [Test]
    public void CountsPerCarset()
    {
        var catalog = Load();
        CollectionAssert.AreEquivalent(ExpectedCounts.Keys, catalog.Carsets.Select(s => s.id), "carsets listed");
        CollectionAssert.AreEquivalent(ExpectedCounts.Keys, catalog.Cars.Select(c => c.carset).Distinct(), "carsets with cars");
        foreach (var kv in ExpectedCounts)
        {
            Assert.AreEqual(kv.Value, catalog.InCarset(kv.Key).Count, kv.Key);
            var row = catalog.GetCarset(kv.Key);
            Assert.AreEqual(kv.Value, row.cars, kv.Key + ": carset row count disagrees with its cars");
            Assert.IsFalse(string.IsNullOrEmpty(row.name), kv.Key + ": no display name");
        }
    }

    [Test]
    public void EveryRarityIsAwardable()
    {
        var catalog = Load();
        for (int r = CarCatalog.MinRarity; r <= CarCatalog.MaxRarity; r++)
            Assert.IsNotEmpty(catalog.ByRarity(r), $"no {r}-star cars");
        Assert.AreEqual(catalog.Count, Enumerable.Range(1, 4).Sum(r => catalog.ByRarity(r).Count));
        Assert.AreEqual(catalog.Count, catalog.AtLeastRarity(1).Count);
        Assert.AreEqual(catalog.ByRarity(4).Count, catalog.AtLeastRarity(4).Count);
        Assert.IsEmpty(catalog.ByRarity(0));
        Assert.IsEmpty(catalog.ByRarity(5));
    }

    [Test]
    public void LookupsAgreeWithTheCarList()
    {
        var catalog = Load();
        foreach (var c in catalog.Cars)
        {
            Assert.AreSame(c, catalog.Get(c.id));
            Assert.AreSame(c, catalog.Get(c.carset, c.number));
            CollectionAssert.Contains(catalog.ByTeam(c.team), c);
            CollectionAssert.Contains(catalog.ByManufacturer(c.manufacturer), c);
            CollectionAssert.Contains(catalog.ByType(c.type), c);
            CollectionAssert.Contains(catalog.ByRarity(c.rarity), c);
        }
        Assert.AreEqual(catalog.Count, catalog.Teams.Sum(t => catalog.ByTeam(t).Count));
        Assert.AreEqual(catalog.Count, catalog.Manufacturers.Sum(m => catalog.ByManufacturer(m).Count));
        Assert.AreEqual(catalog.Count, DriverTypes.All.Sum(t => catalog.ByType(t).Count));
        Assert.IsNull(catalog.Get("nope_1"));
        Assert.IsNull(catalog.Get(null));
        Assert.IsEmpty(catalog.ByTeam("nope"));
        Assert.IsEmpty(catalog.InCarset(null));
    }

    [Test]
    public void KnownDm2CarsCameAcross()
    {
        var catalog = Load();
        // Spot checks against DriverNames.cs.
        var johnson = catalog.Get("cup20_48");
        Assert.IsNotNull(johnson);
        Assert.AreEqual("Johnson", johnson.driver);
        Assert.AreEqual("HEN", johnson.team);
        Assert.IsTrue(catalog.ByDriver("johnson").Contains(johnson));
        // IROC '00: twelve Pontiac legends, all three stars.
        Assert.IsTrue(catalog.InCarset("irc00").All(c => c.manufacturer == "PNT" && c.type == DriverTypes.Legend && c.rarity == 3));
        // DM2 typed irl24 #75 Sato as "Sato"; the export takes his type from irl23.
        Assert.AreEqual(DriverTypes.Closer, catalog.Get("irl24_75").type);
        // Spare livery sprites with no DM2 driver are not cars.
        Assert.IsNull(catalog.Get("cup20_93"));
    }

    [Test]
    public void BadInputIsHandled()
    {
        Assert.IsNull(CarCatalog.FromJson(null));
        Assert.IsNull(CarCatalog.FromJson("   "));
        Assert.IsNull(CarCatalog.FromJson("{ not json"));
        var file = new CarCatalogFile
        {
            cars = new List<CarDef>
            {
                new CarDef { id = "a_1", carset = "a", number = 1, rarity = 9, type = DriverTypes.Rookie },
                new CarDef { id = "a_1", carset = "a", number = 1, rarity = 2 },
                new CarDef { id = "", carset = "a" },
                null,
            },
        };
        var catalog = new CarCatalog(file);
        Assert.AreEqual(1, catalog.Count);
        Assert.AreEqual(4, catalog.Get("a_1").rarity, "rarity clamps to 1-4");
        Assert.AreEqual(0, new CarCatalog(null).Count);
    }
}
